<script setup lang="ts">
import { computed, ref } from 'vue'
import { PhCpu, PhArrowSquareOut, PhCheckCircle, PhInfo, PhPlay, PhArrowRight, PhDownloadSimple, PhBookOpen } from '@phosphor-icons/vue'
import type { Snapshot } from '../../shared/contracts'
import { rankModelRecommendations } from '../../shared/model-recommendations'
import { assetUrl } from '../src/asset-url'

const props = defineProps<{ snapshot: Snapshot }>()
const emit = defineEmits<{ action: [command: string, payload?: unknown]; create: [] }>()
const order = ['wan22-ti2v-5b', 'wan21-t2v-13b', 'ltx-video-2b-095', 'minimax-h3-existing']
const selectedId = ref('wan22-ti2v-5b')
const ranked = computed(() => rankModelRecommendations(/NVIDIA/i.test(props.snapshot.hardware.gpuName) ? props.snapshot.hardware.vramMb : 0, props.snapshot.hardware.ramGb, props.snapshot.hardware.gpuName).sort((a, b) => order.indexOf(a.id) - order.indexOf(b.id)))
const selected = computed(() => ranked.value.find(model => model.id === selectedId.value) ?? ranked.value[0]!)
const hardwareLabel = computed(() => `${props.snapshot.hardware.gpuName || '显卡待识别'} · ${props.snapshot.hardware.vramMb > 0 ? (props.snapshot.hardware.vramMb / 1024).toFixed(1) + ' GB 显存' : '显存待检测'} · ${props.snapshot.hardware.ramGb > 0 ? props.snapshot.hardware.ramGb + ' GB 内存' : '内存待检测'}`)
const h3Generated = computed(() => ['ready', 'busy'].includes(props.snapshot.engine.status) && props.snapshot.templates.some(template => template.id === 'h3-i2v' && template.ready) && props.snapshot.tasks.some(task => task.status === 'completed' && task.params.templateId === 'h3-i2v' && task.outputs.length > 0))
const images: Record<string, string> = Object.fromEntries(order.map(id => [id, `/model-covers/${id}.webp`]))
const coverLabel = (id: string) => id === 'ltx-video-2b-095' ? '官方示例画面' : '官方模板封面'
const tutorialLabel = (source?: string) => source === 'community' ? '社区方案' : '官方教程'
const coverOrigins: Record<string, string> = {
  'wan22-ti2v-5b': 'https://raw.githubusercontent.com/Comfy-Org/workflow_templates/main/templates/video_wan2_2_5B_ti2v-1.webp',
  'wan21-t2v-13b': 'https://raw.githubusercontent.com/Comfy-Org/workflow_templates/main/templates/text_to_video_wan-1.webp',
  'ltx-video-2b-095': 'https://comfyanonymous.github.io/ComfyUI_examples/ltxv/ltxv_text_to_video_0.9.5.webp',
  'minimax-h3-existing': 'https://raw.githubusercontent.com/Comfy-Org/workflow_templates/main/templates/video_minimax_h3_i2v-1.webp',
}
const roles: Record<string, string> = { 'wan22-ti2v-5b': '首推探索', 'wan21-t2v-13b': '轻量备选', 'ltx-video-2b-095': '可选探索', 'minimax-h3-existing': '音画同步' }
const screenshotFailed = ref<Record<string, boolean>>({})
function openReference(url: string) { emit('action', 'native.openReference', { url }) }
function modelState(id: string) { return id === 'minimax-h3-existing' ? (h3Generated.value ? '工作台可用 · 此设备已有作品' : '支持创作工作台 · 请先检查环境') : '使用方式：原生 ComfyUI' }
</script>

<template>
  <section class="model-rec" aria-label="模型推荐与安装教程">
    <div class="hardware-summary"><PhCpu :size="24" /><div><strong>{{ hardwareLabel }}</strong><p>按显存与内存匹配模型，建议从低分辨率短片开始。</p></div></div>
    <div class="recommendation-layout">
      <div class="model-grid" aria-label="模型选择">
        <article v-for="model in ranked" :key="model.id" class="model-card" :class="{ selected: selectedId === model.id }">
          <button class="inspiration" :class="{ 'h3-cover': model.id === 'minimax-h3-existing' }" :aria-label="`查看 ${model.name} 的${tutorialLabel(model.source)}，封面来自对应模型的官方资料`" @click="openReference(model.tutorialUrl)"><img :src="assetUrl(images[model.id]!)" :style="{ objectPosition: model.id === 'wan22-ti2v-5b' ? '50% 35%' : '50% 50%', objectFit: model.id === 'minimax-h3-existing' ? 'contain' : 'cover' }" :alt="`${model.name} ${coverLabel(model.id)}`" loading="lazy" /><span>{{ coverLabel(model.id) }}</span><span class="role-tag">{{ model.id === 'minimax-h3-existing' && model.source === 'community' ? '低配试用' : roles[model.id] }}</span></button>
          <div class="card-content"><h3>{{ model.name }}</h3><p class="purpose">{{ model.purpose }}</p><span class="level" :class="model.level"><component :is="model.level === 'recommended' ? PhCheckCircle : PhInfo" :size="16" />{{ model.levelLabel }}</span><p class="source-note">{{ model.description }}</p><p class="model-state" :class="{ verified: model.id === 'minimax-h3-existing' && h3Generated }">{{ modelState(model.id) }}</p><div class="card-actions"><button class="btn secondary" :aria-pressed="selectedId === model.id" @click="selectedId = model.id">{{ selectedId === model.id ? '正在查看教程' : '查看安装教程' }}<PhArrowRight :size="16" /></button><button class="official-link" :aria-label="`打开 ${model.name} ${tutorialLabel(model.source)}`" @click="openReference(model.tutorialUrl)"><PhArrowSquareOut :size="17" /></button></div></div>
        </article>
      </div>
      <aside class="tutorial-panel" aria-label="所选模型安装详情">
        <header><p class="detail-eyebrow">{{ selected.source === 'community' ? '社区方案' : '官方资料' }} · 安装指南</p><h2>{{ selected.name }}</h2><p class="detail-state">{{ modelState(selected.id) }}</p></header>
        <div class="reference-actions"><button class="btn secondary" @click="openReference(selected.tutorialUrl)"><PhBookOpen :size="17" />{{ tutorialLabel(selected.source) }}<PhArrowSquareOut :size="14" /></button><button class="btn secondary" @click="openReference(selected.repositoryUrl)">模型项目<PhArrowSquareOut :size="14" /></button></div>
        <button class="tutorial-screenshot" :aria-label="`打开 ${selected.name} ${tutorialLabel(selected.source)}原文`" @click="openReference(selected.tutorialUrl)"><img v-if="!screenshotFailed[selected.id]" :src="assetUrl(selected.screenshotPath)" :alt="`${selected.name} ${tutorialLabel(selected.source)}页面截图`" loading="lazy" @error="screenshotFailed[selected.id] = true" /><span v-else class="screenshot-empty"><PhBookOpen :size="30" />打开{{ tutorialLabel(selected.source) }}原文</span><span class="screenshot-caption">{{ tutorialLabel(selected.source) }}截图 · 点击打开原文<PhArrowSquareOut :size="14" /></span></button>
        <button class="text-button cover-source" @click="openReference(coverOrigins[selected.id]!)">{{ coverLabel(selected.id) }} · 查看封面来源<PhArrowSquareOut :size="14" /></button><h3 class="detail-heading">安装步骤</h3><ol class="install-steps"><li v-for="(step, index) in selected.steps" :key="step"><span>{{ index + 1 }}</span><p>{{ step }}</p></li></ol>
        <div class="initial-settings"><strong>建议首次试跑</strong><p>{{ selected.initial.width }} × {{ selected.initial.height }} · {{ selected.initial.frames }} 帧</p><p>{{ selected.initial.note }}</p></div>
        <h3 class="detail-heading">需要的模型文件 <small>{{ selected.downloads.length }} 个</small></h3><p class="files-help">点击文件名打开{{ selected.source === 'community' ? '发布者' : '官方' }}文件页；文件放入 ComfyUI/models 下的对应子目录。</p><ul class="file-list"><li v-for="file in selected.downloads" :key="file.name"><button @click="openReference(file.url)"><PhDownloadSimple :size="16" /><span>{{ file.name }}</span><PhArrowSquareOut :size="14" /></button><code>models/{{ file.folder }}/</code></li></ul>
        <details class="conditions"><summary>配置要求与推荐依据</summary><p class="evidence-note">{{ selected.sourceNote }}</p><ul><li v-for="condition in selected.conditions" :key="condition">{{ condition }}</li></ul></details>
        <button v-if="selected.id === 'minimax-h3-existing'" class="btn primary create-button" @click="emit('create')"><PhPlay :size="17" weight="fill" />打开 H3 创作工作台</button>
        <p v-else class="manual-note"><PhInfo :size="17" />请按教程在原生 ComfyUI 中安装和运行此模型。启动器创作工作台目前支持 H3。</p>
      </aside>
    </div>
  </section>
</template>


<style scoped>
.model-rec{font-size:14px;line-height:1.6;min-width:0}.model-rec h2,.model-rec h3,.model-rec p{margin:0}
.hardware-summary{display:flex;align-items:center;gap:16px;padding:22px 24px;border:1px solid var(--border);border-radius:18px;background:var(--surface);margin-bottom:26px}.hardware-summary>svg{color:var(--accent);flex:none}.hardware-summary>div{min-width:0;overflow-wrap:anywhere}.hardware-summary strong{font-size:14px;font-weight:600;line-height:1.7}.hardware-summary p{color:var(--muted);font-size:12px;line-height:1.8;margin-top:4px}
.recommendation-layout{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(320px,1fr);gap:24px;align-items:start}.model-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.model-card{background:var(--surface);border:1px solid var(--border);border-radius:18px;min-width:0;overflow:hidden}.model-card.selected{border-color:var(--accent);box-shadow:0 0 0 1px var(--accent)}.inspiration{position:relative;display:block;padding:0;border:0;width:100%;background:var(--control);cursor:pointer;overflow:hidden}.inspiration img{display:block;width:100%;height:auto;aspect-ratio:1.8;max-height:220px;object-fit:cover;background:var(--control)}.inspiration.h3-cover img{padding:16px;background:#000;box-sizing:border-box}.inspiration>span{position:absolute;left:12px;bottom:12px;padding:4px 8px;border-radius:6px;background:#1d292ee6;color:#fff;font-size:12px;line-height:1.5}.inspiration>.role-tag{top:12px;bottom:auto;color:var(--accent);background:var(--surface);font-weight:600}
.card-content{padding:20px}.card-content h3{font-size:17px;font-weight:600;line-height:1.5;margin-bottom:7px;letter-spacing:-.2px}.purpose{color:var(--muted);font-size:13px;line-height:1.8;min-height:42px}.level{display:flex;align-items:center;gap:6px;color:var(--muted);font-size:12px;margin:14px 0 9px}.level>svg{flex:none}.level.recommended{color:var(--accent)}.level.conditional{color:var(--warning)}.source-note{color:var(--muted);font-size:13px;line-height:1.8;min-height:70px}.model-state{font-size:12px;color:var(--muted);line-height:1.8;margin-top:12px!important}.model-state.verified{color:var(--accent)}.card-actions{display:flex;gap:8px;align-items:center;margin-top:18px}.card-actions .btn{flex:1;min-width:0;font-size:13px;padding:8px 10px;gap:7px}.official-link{min-width:44px;height:44px;display:inline-flex;align-items:center;justify-content:center;color:var(--muted);background:var(--surface);border:1px solid var(--border);border-radius:11px;cursor:pointer}
.tutorial-panel{min-width:0;border:1px solid var(--border);border-radius:18px;padding:26px;background:var(--surface)}.detail-eyebrow{color:var(--muted);font-size:12px;letter-spacing:.06em;margin-bottom:8px!important}.tutorial-panel h2{font-size:23px;font-weight:600;line-height:1.45;letter-spacing:-.4px;overflow-wrap:anywhere}.detail-state{font-size:12px;color:var(--muted);line-height:1.8;margin-top:9px!important}.reference-actions{display:flex;flex-wrap:wrap;gap:9px;margin:20px 0}.reference-actions .btn{min-height:44px;font-size:13px;padding:8px 13px}.tutorial-screenshot{width:100%;display:block;background:var(--control);padding:0;color:var(--muted);border:1px solid var(--border);border-radius:12px;cursor:pointer;overflow:hidden}.tutorial-screenshot img{width:100%;display:block;aspect-ratio:1.65;object-fit:cover;object-position:top}.screenshot-empty{min-height:160px;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:10px;font-size:14px}.screenshot-caption{display:flex;justify-content:space-between;gap:8px;align-items:center;padding:11px 12px;font-size:12px;text-align:left;line-height:1.7}.detail-heading{font-size:16px;font-weight:600;margin:26px 0 14px!important;display:flex;align-items:center;justify-content:space-between;gap:10px}.detail-heading small{color:var(--muted);font-size:12px;font-weight:400;flex:none}.install-steps{list-style:none;margin:0;padding:0}.install-steps li{display:flex;gap:12px;margin-bottom:14px}.install-steps li>span{width:25px;height:25px;background:var(--control);border-radius:50%;flex:none;display:flex;align-items:center;justify-content:center;color:var(--text);font-size:12px}.install-steps p{font-size:13px;color:var(--muted);line-height:1.9;overflow-wrap:anywhere}
.initial-settings{background:var(--control);border:1px solid var(--border);border-radius:12px;padding:16px;margin-top:22px}.initial-settings strong{font-size:13px;font-weight:600}.initial-settings p{font-size:12px;color:var(--muted);line-height:1.8;margin-top:6px}.files-help{font-size:12px;color:var(--muted);line-height:1.8;margin-bottom:12px!important}.file-list{list-style:none;padding:0;margin:0}.file-list li{padding:13px 0;border-top:1px solid var(--border)}.file-list button{display:flex;align-items:center;gap:8px;width:100%;text-align:left;padding:6px 0;min-height:44px;background:none;border:none;color:var(--accent);cursor:pointer;font:inherit;font-size:13px;line-height:1.7}.file-list button span{flex:1;min-width:0;overflow-wrap:anywhere}.file-list button svg{flex:none}.file-list code{display:block;padding-left:24px;font-size:12px;color:var(--muted);overflow-wrap:anywhere;line-height:1.8}.conditions{margin-top:22px;border-top:1px solid var(--border);padding-top:12px;font-size:12px;color:var(--muted);line-height:1.9}.conditions summary{cursor:pointer;min-height:44px;display:flex;align-items:center;color:var(--text);font-size:13px}.conditions ul{padding-left:18px;margin:0}.conditions li{margin:8px 0}.create-button{width:100%;margin-top:24px}.manual-note{display:flex;gap:8px;font-size:12px;color:var(--muted);line-height:1.8;margin-top:20px!important}.manual-note svg{flex:none;margin-top:3px}.text-button{display:inline-flex;align-items:center;gap:7px;padding:10px 0;border:0;background:none;font:inherit;font-size:12px;color:var(--accent);min-height:44px;text-align:left;cursor:pointer}
button:focus-visible,summary:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
@media(max-width:1200px){.recommendation-layout{grid-template-columns:minmax(0,1.4fr) minmax(300px,1fr);gap:20px}.model-grid{gap:16px}.card-content{padding:18px}.source-note{min-height:92px}.tutorial-panel{padding:22px}.card-actions{flex-wrap:wrap}.card-actions .btn{font-size:12px}.card-content h3{font-size:16px}}
@media(max-width:1000px){.recommendation-layout{grid-template-columns:1fr}.model-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.source-note{min-height:48px}.tutorial-screenshot{max-width:640px}.hardware-summary{align-items:flex-start}.card-actions .btn{font-size:13px}}
@media(max-width:600px){.model-grid{grid-template-columns:1fr;gap:18px}.hardware-summary{padding:20px;gap:12px}.source-note,.purpose{min-height:0}.card-content{padding:20px}.tutorial-panel{padding:20px}.tutorial-panel h2{font-size:22px}.inspiration img{max-height:240px;aspect-ratio:1.75}}
</style>
